const std = @import("std");

fn sumRange(arr: []i32, start: usize, end: usize) i32 {
    var sum: i32 = 0;
    for (start..end) |i| sum += arr[i];
    return sum;
}

pub fn main() !void {
    const arr = [_]i32{ 1, 2, 3, 4, 5, 6, 7, 8 };
    const mid = arr.len / 2;

    const t1 = try std.Thread.spawn(.{}, sumRange, .{ arr, 0, mid });
    const t2 = try std.Thread.spawn(.{}, sumRange, .{ arr, mid, arr.len });

    const r1 = t1.join();
    const r2 = t2.join();
    const total = r1 + r2;

    std.debug.print("Sum: {}\n", .{total});
}

